#!/usr/bin/env python3
"""Original PNG/CSV/Vega-Lite charts. Run in checking repo uv environment."""
import csv,json,shutil,sys
from pathlib import Path
import vl_convert as vlc
P=Path(sys.argv[1]);C=P/'charts';C.mkdir(exist_ok=True)
BASE={'$schema':'https://vega.github.io/schema/vega-lite/v5.json','config':{'font':'Arial, sans-serif','view':{'stroke':None},'axis':{'labelColor':'#343d46','titleColor':'#343d46','gridColor':'#dedfdc','labelFontSize':12,'titleFontSize':13},'legend':{'orient':'top','title':None,'labelFontSize':12,'labelLimit':530},'title':{'anchor':'start','fontSize':19,'subtitleFontSize':12,'subtitleColor':'#4b5563'},'background':'#fbfaf7'}}
def emit(name,spec,numeric):
 shutil.copy2(P/'data'/(name+'.csv'),C/(name+'.csv'))
 spec={**BASE,**spec,'data':{'url':f'charts/{name}.csv','format':{'type':'csv','parse':{k:'number' for k in numeric}}}}
 (C/(name+'.vl.json')).write_text(json.dumps(spec,indent=2,ensure_ascii=False)+'\n')
 png=json.loads(json.dumps(spec));rows=list(csv.DictReader((C/(name+'.csv')).open()))
 for r in rows:
  for k in numeric:r[k]=float(r[k])
 png['data']={'values':rows}
 (C/(name+'.png')).write_bytes(vlc.vegalite_to_png(png,scale=2))
rows=list(csv.DictReader((P/'data/1-spending-gdp.csv').open()));order=[r['label'] for r in sorted(rows,key=lambda r:float(r['peak_spend_pct_gdp']),reverse=True)]
emit('1-spending-gdp',{'width':610,'height':{'step':32},'title':{'text':'A close twentieth-century precedent; larger earlier booms','subtitle':['Annual spending / GDP (%). Historical domestic series versus global company proxy.','AI allocation and pace are scenarios, not bounds on measured domestic AI investment.']},'encoding':{'y':{'field':'label','type':'nominal','sort':order,'title':None,'axis':{'labelLimit':270}},'x':{'field':'peak_spend_pct_gdp','type':'quantitative','title':'Spending as a share of GDP (%)','scale':{'domain':[0,7.1]}},'tooltip':[{'field':'label','title':'Case'},{'field':'peak_spend_pct_gdp','type':'quantitative','format':'.2f','title':'GDP share (%)'},{'field':'scope','title':'Coverage'}]},'layer':[{'mark':{'type':'bar','cornerRadiusEnd':2},'params':[{'name':'pick','select':{'type':'point','fields':['status']},'bind':'legend'}],'encoding':{'color':{'field':'status','type':'nominal','scale':{'domain':['Historical private industry','Public programme','Article proxy','AI scenario'],'range':['#126782','#89969d','#b86412','#cf9a45']},'legend':{'direction':'vertical'}},'opacity':{'condition':{'param':'pick','value':1},'value':.2}}},{'mark':{'type':'text','align':'left','dx':5,'color':'#253341'},'encoding':{'text':{'field':'peak_spend_pct_gdp','format':'.1f'}}}]},['year','peak_spend_pct_gdp'])
emit('2-revenue-and-capex',{'title':{'text':'Growth paths for railways, telecom and AI','subtitle':['Each series starts at 100 independently; common logarithmic scale.','AI: October revenue run rate and Q3 capex estimates; adjacent periods, different cohort.']},'facet':{'row':{'field':'precedent','type':'nominal','sort':['UK railways','US railways','US telecom','AI: estimates'],'header':{'labelFontSize':15,'labelFontWeight':'bold','labelAngle':0,'labelAlign':'left','title':None}}},'spec':{'width':560,'height':135,'mark':{'type':'line','point':{'filled':True,'size':38}},'params':[{'name':'seriespick','select':{'type':'point','fields':['series']},'bind':'legend'}],'encoding':{'x':{'field':'period','type':'ordinal','title':'Calendar year','axis':{'labelAngle':0}},'y':{'field':'index_first_observation_100','type':'quantitative','title':'Index; first value = 100 (log)','scale':{'type':'log','domain':[45,1000]},'axis':{'values':[50,100,200,500,1000]}},'color':{'field':'series','type':'nominal','scale':{'domain':['Capex','Revenue'],'range':['#b86412','#126782']}},'strokeDash':{'condition':{'test':"datum.series === 'Capex'",'value':[1,0]},'value':[7,2]},'opacity':{'condition':{'param':'seriespick','value':1},'value':.2},'tooltip':[{'field':'precedent'},{'field':'period','title':'Year'},{'field':'series'},{'field':'index_first_observation_100','type':'quantitative','format':'.1f','title':'Index'},{'field':'basis'}]}},'resolve':{'scale':{'x':'independent'}}},['year','index_first_observation_100'])
# A separate segment chart avoids suggesting a common capex cohort for long-distance and wireless.
shutil.copy2(P/'data/telecom-segments.csv',P/'data/3-telecom-segments.csv')
emit('3-telecom-segments',{'width':560,'height':230,'title':{'text':'Telecom revenue moved between businesses','subtitle':['FCC end-user revenue, 2000 = 100. Toll is broader than a fibre-only cohort.']},'mark':{'type':'line','point':True},'params':[{'name':'segmentpick','select':{'type':'point','fields':['series']},'bind':'legend'}],'encoding':{'x':{'field':'year','type':'quantitative','title':'Year','axis':{'format':'d','tickMinStep':1}},'y':{'field':'index_2000_100','type':'quantitative','title':'Revenue index (2000 = 100)','scale':{'domain':[60,155]}},'color':{'field':'series','type':'nominal','scale':{'domain':['Long-distance / toll','Wireless','Local','Total end-user'],'range':['#b86412','#126782','#4d8060','#6c747b']},'legend':{'direction':'vertical'}},'opacity':{'condition':{'param':'segmentpick','value':1},'value':.2},'tooltip':[{'field':'year'},{'field':'series'},{'field':'revenue_bn','type':'quantitative','title':'Revenue USD bn','format':'.3f'},{'field':'change_from_2000_pct','type':'quantitative','title':'Change since 2000 (%)','format':'.1f'}]}},['year','revenue_bn','index_2000_100','change_from_2000_pct'])
